pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;

    // Heavy penalty for nearly empty residuals
    if post_residual < 2 {
        score -= 2500.0 * (2 - post_residual) as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Encourage fits that leave enough room for the next item
        score += 120.0 * (next_item_size - post_residual) as f64;
    }

    // New bin candidate adjustment
    if bin_residual == bin_capacity {
        if item_size > 95 {
            score -= 35.0;
        } else if item_size > 85 {
            score -= 20.0;
        } else if item_size > 75 {
            score -= 10.0;
        }
    }

    // Residual usage ratio
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio < 0.12 {
        score += 3.0 * (0.12 - ratio) * bin_capacity as f64;
    } else if ratio > 0.40 {
        score -= 1.5 * (ratio - 0.40) * bin_capacity as f64;
    }

    // Look‑ahead for next item
    let diff = next_item_size as i32 - post_residual as i32;
    if diff > 0 {
        score += 50.0 * diff as f64;
    } else {
        score -= 0.5 * diff.abs() as f64;
    }

    // Penalize deviation from mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * mean_diff.powi(2);

    // Fitting bin count effect
    let fit_log = (fitting_bins_count as f64 + 1.0).ln();
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        score += 0.25 * fit_log;
    }

    // Open bin penalty grows after 6 open bins
    if open_bins_count > 6 {
        let excess = open_bins_count - 6;
        score += 2.0 * (excess as f64).powi(2);
    }

    // Progress‑based scaling
    let progress = step_index as f64 / total_items as f64;
    score += progress.powf(1.5) * post_residual as f64 * 0.7;

    // High usage penalty
    let used = bin_capacity - bin_residual;
    if used as f64 > 0.93 * bin_capacity as f64 {
        score -= 0.2 * post_residual as f64;
    }

    // Late‑stage aggressive compaction
    if progress > 0.9 {
        let extra = 1.0 + 0.35 * ((progress - 0.9) / 0.1).min(1.0);
        score += 4.5 * post_residual as f64 * extra;
    }
    if progress > 0.8 {
        let factor = 1.0 + 0.25 * ((progress - 0.8) / 0.2).min(1.0);
        score += 5.5 * post_residual as f64 * factor;
    }

    score
