    if diff_mean > 0.0 {
        score += 0.4 * diff_mean;
    } else {
        score -= 0.2 * diff_mean.abs();
    }

    // 4. Open‑bin pressure – discourage too many open bins
    if open_bins_count > 8 {
        score += 12.0 * (open_bins_count as f64 - 8.0);
    }

    // 5. Near‑end penalty – leftover space becomes more expensive
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.97 {
        score += 4.0 * post_residual as f64;
    }

    // 6. Singleton fit bonus – only one bin can accept the item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // 7. New‑bin bias – favor fresh bins for large items
    if bin_residual == bin_capacity {
        if item_size > 95 {
            score -= 35.0;
        } else if item_size > 85 {
            score -= 20.0;
        } else if item_size > 75 {
            score -= 10.0;
        }
    }

    // 8. Size ratio tweak – discourage packing very small or too large items
    let ratio = item_size as f64 / bin_capacity as f64;
    if ratio < 0.15 {
        score += 12.0;
    } else if ratio > 0.97 {
        score -= 22.0;
    }

    // 9. Lookahead penalty – next item would fit only if this bin is almost full
    if next_item_size > 0 && next_item_size < bin_capacity {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // 10. Residual‑ratio penalty for tiny items in moderately large gaps
    if residual_ratio > 0.35 && ratio < 0.12 {
        score += 6.0;
    }

    // 11. Strong new‑bin incentive when no bin fits and many are open
    if bin_residual == bin_capacity && fitting_bins_count == 0 && open_bins_count > 4 {
