    // Start from the raw residual as a baseline
    let mut score = post_residual as f64;

    // 1. Tight dead‑space avoidance – large penalty for very small gaps
    if post_residual < 3 {
        score += 1500.0 * (3 - post_residual) as f64;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 150.0 * (next_item_size - post_residual) as f64;
    }

    // 2. Balance against the current mean residual
    if (post_residual as f64) > mean_residual + 5.0 {
        score += 0.8 * ((post_residual as f64) - mean_residual - 5.0);
    } else if (post_residual as f64) < mean_residual - 5.0 {
        score -= 0.2 * (mean_residual - (post_residual as f64) - 5.0);
    }

    // 3. Pressure to close bins when many remain open
    if open_bins_count > 8 {
        score += 12.0 * (open_bins_count as f64 - 8.0);
    }

    // 4. Near‑end penalty – any leftover space becomes costly
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score += 3.0 * (post_residual as f64);
    }

    // 5. Singleton fit bonus – only bin that can hold the item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

