pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual left after placement
    let mut score = post_residual as f64;

    // Handle empty‑bin (new‑bin) cases with a size‑dependent penalty
    if bin_residual == bin_capacity {
        // Prefer opening a new bin for very large items
        if item_size > 90 {
            score -= 25.0;
        } else if item_size > 80 {
            score -= 15.0;
        } else if item_size > 70 {
            score -= 5.0;
        }

        // Penalise starting a new bin for small items (avoid wasted capacity)
        let half_cap = bin_capacity / 2;
        if item_size < half_cap {
            score += 5.0;
        }
    }

    // Residual ratio penalty (non‑linear)
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio > 0.25 {
        // Quadratic penalty for high waste
        let excess = residual_ratio - 0.25;
        score += 3.0 * excess * excess * bin_capacity as f64;
    } else {
        // Small penalty for very tight fits
        score += 10.0 * residual_ratio;
    }

    // Look‑ahead penalty/reward using the next item size
    if next_item_size > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            // Potential future waste: penalise with sub‑linear growth
            score += 30.0 * ((diff as f64).powf(0.9));
        } else {
            // Slight reward if the next item can fit into the remaining space
            score -= 0.1 * diff.abs() as f64;
        }
    }

    // Mean residual deviation (quadratic)
    let mean_diff = post_residual as f64 - mean_residual;
    if mean_diff > 0.0 {
        score += 0.1 * mean_diff * mean_diff;
    } else {
        score -= 0.1 * mean_diff.abs() * mean_diff.abs();
    }

    // Fitting bins count: discourage many poor options, heavily penalise only one
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        let log2 = (fitting_bins_count as f64).ln() / 2.0_f64.ln();
        score += 0.5 * log2;
    }

    // Open bins count: heavier penalty when many bins are open
    if open_bins_count > 7 {
        let over = open_bins_count - 7;
        score += 2.0 * over as f64;
    }

    // Progress‑based adjustment: as we near the end we can tolerate more waste
    let progress = step_index as f64 / total_items as f64;
    let progress_factor = if progress > 0.9 {
        3.0
    } else if progress > 0.75 {
        1.5
    } else {
        1.0
    };
    score += progress_factor * post_residual as f64;

    // Tight usage penalty: if used > 90% of bin, slightly penalise remaining waste
    let used = bin_capacity - bin_residual;
    if (used as f64) > 0.9 * bin_capacity as f64 {
        score -= 0.3 * post_residual as f64;
    }

    // Late‑stage incentive to accept more waste
    if progress > 0.8 {
        let factor = 1.0 + 0.2 * ((progress - 0.8) / 0.2).min(1.0);
        score += 5.0 * post_residual as f64 * factor;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // start with the raw residual
    let mut score = post_residual as f64;

    // penalise opening a brand‑new bin for very large items
    if bin_residual == bin_capacity {
        if item_size > 85 {
            score -= 28.0;
        } else if item_size > 70 {
            score -= 15.0;
        }
    }

    // residual ratio – encourage mid‑range fill
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio < 0.15 {
        score += 2.0 * (0.15 - ratio) * bin_capacity as f64;
    }
    if ratio > 0.35 {
        score -= 1.2 * (ratio - 0.35) * bin_capacity as f64;
    }

    // look‑ahead with the next item
    if next_item_size > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            score += 40.0 * diff as f64;
        } else {
            score -= 0.3 * diff.abs() as f64;
        }
    }

    // deviation from mean residual – squared for sharper penalty
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.4 * mean_diff.powi(2);

    // number of fitting bins – logarithmic dampening
    let fit_log = (fitting_bins_count as f64 + 1.0).ln();
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        score += 0.2 * fit_log;
    }

    // open bins penalty – quadratic once past four
    let open_pen = if open_bins_count > 4 {
        ((open_bins_count - 4) as f64).powi(2) * 1.5
    } else {
        0.0
    };
    score += open_pen;

    // progress‑dependent residual reward
    let progress = step_index as f64 / total_items as f64;
    score += progress.powf(1.5) * post_residual as f64 * 0.8;

    // high usage bonus
    let used = bin_capacity - bin_residual;
    if used as f64 > 0.92 * bin_capacity as f64 {
        score -= 0.15 * post_residual as f64;
    }

    // late‑stage aggressive packing
    if progress > 0.9 {
        let extra = 1.0 + 0.3 * ((progress - 0.9) / 0.1).min(1.0);
        score += 4.0 * post_residual as f64 * extra;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
