    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score starts from the post‑fit residual
    let mut score = post_residual as f64;

    // 1. Tight dead‑space penalty for very small gaps
    if post_residual < 5 {
        score += (5 - post_residual) as f64 * 200.0;
    }

    // 2. Mean residual alignment
    let diff_mean = (post_residual as f64) - mean_residual;
    if diff_mean > 0.0 {
        score += 0.5 * diff_mean;
    } else {
        score -= 0.3 * diff_mean.abs();
    }

    // 3. Open‑bin pressure – discourage leaving many bins open
    if open_bins_count > 10 {
        score += 15.0 * (open_bins_count as f64 - 10.0);
    }

    // 4. Near‑end penalty – any leftover space becomes costly
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 {
        score += 5.0 * post_residual as f64;
    }

    // 5. Singleton fit bonus – only bin that can hold the item
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // 6. New‑bin bias – prefer a fresh bin for very large items
    if bin_residual == bin_capacity {
        if item_size > 90 {
            score -= 30.0;
        } else if item_size > 80 {
            score -= 20.0;
        } else if item_size > 70 {
            score -= 10.0;
        }
    }

    // 7. Size ratio tweak – discourage packing tiny items into almost‑full bins
    let ratio = item_size as f64 / bin_capacity as f64;
    if ratio < 0.2 {
        score += 10.0;
    } else if ratio > 0.95 {
        score -= 20.0;
    }

    // 8. Lookahead penalty – if next item would fit only if this bin is almost full
    if next_item_size > 0 && next_item_size < bin_capacity {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 9. Residual‑ratio penalty – small item into a bin with large residual
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio > 0.3 && ratio < 0.15 {
        score += 5.0;
    }

    // 10. Strong new‑bin incentive when no open bin fits and many bins are open
    if bin_residual == bin_capacity
        && fitting_bins_count == 0
        && open_bins_count > 5
    {
        score -= 50.0;
    }

    score
